globalThis.SITE_ASSETS = {"/achievements.js":{"mime":"application/javascript; charset=utf-8","base64":""},"/assistant.js":{"mime":"application/javascript; charset=utf-8","base64":""},"/auth.js":{"mime":"application/javascript; charset=utf-8","base64":""},"/index.html":{"mime":"text/html; charset=utf-8","base64":""},"/mock10.js":{"mime":"application/javascript; charset=utf-8","base64":""},"/oge-guide.png":{"mime":"image/png","base64":""},"/progress-scope.js":{"mime":"application/javascript; charset=utf-8","base64":""}};
const SUPABASE_URL = 'https://hwggubjyeavxgyoqqelw.supabase.co';
const SUPABASE_KEY = 'sb_publishable_6EzzcMnrKlFWXkVaSP3jzA_gV9Eq5tT';
const limits = new Map();

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {status, headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
}

async function authenticated(request) {
  const bearer = request.headers.get('authorization');
  if (bearer?.startsWith('Bearer ')) {
    const response = await fetch(SUPABASE_URL + '/auth/v1/user', {
      headers:{apikey:SUPABASE_KEY, authorization:bearer}
    });
    if (response.ok) {
      const user = await response.json();
      if (user.id && user.user_metadata?.role === 'teacher' && user.email?.toLowerCase() === 'dilyarakirbi@mail.ru') return 'teacher:' + user.id;
    }
  }
  return null;
}

function allowed(identity) {
  const now = Date.now();
  if (limits.size > 3000) for (const [key, value] of limits) if (now - value.start > 60_000) limits.delete(key);
  const value = limits.get(identity);
  if (!value || now - value.start > 60_000) { limits.set(identity,{start:now,count:1}); return true; }
  value.count++;
  return value.count <= 6;
}

async function ask(request, env) {
  const origin = request.headers.get('origin');
  if (origin !== new URL(request.url).origin) return json({error:'Недопустимый запрос.'},403);
  if (Number(request.headers.get('content-length') || 0) > 5000) return json({error:'Сообщение слишком длинное.'},413);
  let data;
  try { data = await request.json(); } catch { return json({error:'Не удалось прочитать сообщение.'},400); }
  const message = String(data.message || '').trim();
  if (message.length < 2 || message.length > 500) return json({error:'Напиши вопрос до 500 символов.'},400);
  const identity = await authenticated(request);
  if (!identity) return json({error:'Пока помощник доступен только учителю для проверки.'},401);
  if (!allowed(identity)) return json({error:'Подожди минуту перед следующим вопросом.'},429);
  if (!env.GIGACHAT_PROXY_URL || !env.GIGACHAT_PROXY_SECRET)
    return json({error:'Помощник пока настраивается. Попробуй позже.'},503);

  const history = Array.isArray(data.history) ? data.history.slice(-6).filter(x =>
    x && ['user','assistant'].includes(x.role) && typeof x.text === 'string' && x.text.length <= 600
  ) : [];
  const context = String(data.context || '').slice(0,80);
  const proxy = new URL(env.GIGACHAT_PROXY_URL);
  if (proxy.protocol !== 'https:' || proxy.pathname !== '/assistant')
    return json({error:'Помощник пока настраивается. Попробуй позже.'},503);
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(),25_000);
  try {
    const response = await fetch(proxy.toString(), {
      method:'POST', signal:controller.signal,
      headers:{'x-site-assistant-secret':env.GIGACHAT_PROXY_SECRET,'content-type':'application/json'},
      body:JSON.stringify({message,history,context})
    });
    if (!response.ok) return json({error:'ИИ временно недоступен. Попробуй позже.'},502);
    const result = await response.json();
    const answer = String(result.answer || '').trim();
    if (!answer) return json({error:'Ответ не получен. Попробуй ещё раз.'},502);
    return json({answer});
  } catch (error) {
    console.error('GigaChat request failed',error?.name || 'Error',error?.message || 'Unknown failure');
    return json({error:'Не удалось связаться с ИИ. Попробуй ещё раз.'},502);
  }
  finally { clearTimeout(timeout); }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/api/assistant') {
      if (request.method !== 'POST') return json({error:'Метод не поддерживается.'},405);
      return ask(request, env);
    }
    if (!['GET','HEAD'].includes(request.method)) return new Response('Method not allowed',{status:405});
    const pathname = url.pathname === '/' ? '/index.html' : url.pathname;
    const asset = globalThis.SITE_ASSETS[pathname];
    if (!asset) return new Response('Not found',{status:404});
    const bytes = Uint8Array.from(atob(asset.base64), x => x.charCodeAt(0));
    return new Response(request.method === 'HEAD' ? null : bytes, {
      headers:{'content-type':asset.mime,'cache-control':pathname === '/index.html' || pathname.endsWith('.js') ? 'no-cache' : 'public, max-age=86400'}
    });
  }
};
